const settingsKey='temlogoali.settings.v1';
export const MARKET_DEFAULTS={domain:'temlogoali.com.br',domainPurchased:true,commission:0,provider:'pending',pix:true,card:true,minutesPerKm:5,regions:[{name:'Cianorte',from:'87200000',to:'87299999'},{name:'Maringá',from:'87000000',to:'87199999'}],stores:[{id:0,name:'Casa Aurora',city:'Cianorte',cep:'87200000',from:'87200000',to:'87299999',rate:250,maxKm:10,cutoff:'15:00',status:'active',seal:'official',documents:[true,true,true]},{id:1,name:'Essencial Concept',city:'Maringá',cep:'87000000',from:'87000000',to:'87199999',rate:200,maxKm:15,cutoff:'15:00',status:'active',seal:'indicated',documents:[false,false,false]},{id:2,name:'Verde & Vida',city:'Cianorte',cep:'87200000',from:'87200000',to:'87299999',rate:180,maxKm:8,cutoff:'15:00',status:'active',seal:'none',documents:[false,false,false]}],modules:[],storeModules:{},coupons:[],freeShippingMinimum:0,notifications:{emailProvider:'Não configurado',whatsappProvider:'Não configurado',email:'Seu pedido {pedido}: {status}. Acompanhe na sua conta.',whatsapp:'Tem Logo Ali: pedido {pedido} — {status}. Consulte sua conta.'},sealRules:{daily:100,reviewMonths:6},audit:[]};

export const EXTRA_DEMO_STORES=[{"id":100,"name":"Lar & Luz","city":"Cianorte","cep":"87200000","initial":"ll","desc":"Iluminação, móveis e decoração","from":"87200000","to":"87299999","rate":200,"maxKm":15,"routeKm":3.4,"cutoff":"15:00","status":"active","seal":"none","documents":[false,false,false],"company":"Lar & Luz · demonstração","street":"Rua Demonstrativa","number":"400","neighborhood":"Centro","state":"PR"},{"id":101,"name":"Jardim de Casa","city":"Cianorte","cep":"87200000","initial":"jc","desc":"Plantas e cuidado com o jardim","from":"87200000","to":"87299999","rate":200,"maxKm":15,"routeKm":3.4,"cutoff":"15:00","status":"active","seal":"none","documents":[false,false,false],"company":"Jardim de Casa · demonstração","street":"Rua Demonstrativa","number":"500","neighborhood":"Centro","state":"PR"},{"id":102,"name":"Conecta Maringá","city":"Maringá","cep":"87000000","initial":"cm","desc":"Tecnologia para o seu dia a dia","from":"87000000","to":"87199999","rate":200,"maxKm":15,"routeKm":3.4,"cutoff":"15:00","status":"active","seal":"none","documents":[false,false,false],"company":"Conecta Maringá · demonstração","street":"Rua Demonstrativa","number":"600","neighborhood":"Centro","state":"PR"}];
MARKET_DEFAULTS.stores.push(...EXTRA_DEMO_STORES);
export function readMarketplace(){try{const config={...structuredClone(MARKET_DEFAULTS),...JSON.parse(localStorage.getItem(settingsKey)||'{}')};for(const seed of EXTRA_DEMO_STORES)if(!config.stores.some(s=>s.id===seed.id))config.stores.push(structuredClone(seed));return config}catch{return structuredClone(MARKET_DEFAULTS)}}
export function saveMarketplace(config,action,reason='Configuração do protótipo',actor='Administrador'){if(!reason.trim())throw Error('Informe o motivo.');config.audit=[...(readMarketplace().audit||[]),{at:new Date().toISOString(),actor,action,reason}];localStorage.setItem(settingsKey,JSON.stringify(config));}
export function auditMarketplace(action,reason,actor='Administrador'){saveMarketplace(readMarketplace(),action,reason,actor)}
export function sellerContext(){try{return Number(sessionStorage.getItem('temlogoali.seller-context')||0)}catch{return 0}}
export function postalRegion(cep,config=readMarketplace()){const clean=String(cep||'').replace(/\D/g,'');if(!/^\d{8}$/.test(clean))return null;return config.regions.find(r=>clean>=r.from&&clean<=r.to)||null}
export function validateEstablishment(store,config=readMarketplace()){
 const origin=postalRegion(store.cep,config);
 if(!origin||origin.name!==store.city)throw Error('O CEP físico deve pertencer à cidade cadastrada da unidade. Cadastre outra loja ou filial para outra cidade.');
 return origin;
}
export function establishmentSnapshot(store){return {id:store.id,name:store.name,company:store.company||'',cnpj:store.cnpj||'',city:store.city,cep:store.cep,street:store.street||'',number:store.number||'',neighborhood:store.neighborhood||'',state:store.state||'',complement:store.complement||''}}
export function establishmentAddress(store){return store?.street?`${store.street}, ${store.number||'s/n'} · ${store.neighborhood||''} · ${store.city} / ${store.state||''} · CEP ${store.cep}${store.complement?' · '+store.complement:''}`:'Endereço completo da unidade ainda não cadastrado';}
export function pickupAllowed(store,cep,config=readMarketplace()){if(!store)return false;const buyer=postalRegion(cep,config),origin=postalRegion(store.cep,config);return !!buyer&&!!origin&&store.city===origin.name&&buyer.name===origin.name&&store.status==='active'}
export function sealMetrics(orders,store,now=new Date()){const end=new Date(now),start=new Date(end);start.setMonth(start.getMonth()-6);const days=Math.max(1,Math.ceil((end-start)/86400000));const buckets={},seen=new Set();let total=0;for(const o of orders){if(o.demoData)continue;if(seen.has(o.id))continue;seen.add(o.id);if(!o.suborders.some(s=>s.store===store))continue;const d=new Date(o.createdAt);if(d>end)continue;const key=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).format(d);buckets[key]=(buckets[key]||0)+1;if(d>=start&&d<=end)total++;}return {peak:Math.max(0,...Object.values(buckets)),average:total/days,total,days,from:start.toISOString()}}
export function sealSVG(type){const official=type==='official',color=official?'#80611d':'#126d59',label=official?'LOJA OFICIAL':'LOJA INDICADA';return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 230 56" role="img" aria-label="${label}"><rect x="1" y="1" width="228" height="54" rx="27" fill="${official?'#fff4d7':'#e8f6ee'}" stroke="${color}"/><path d="M29 9 43 15v13c0 9-14 18-14 18S15 37 15 28V15Z" fill="${color}"/><path d="m22 27 5 5 9-11" fill="none" stroke="white" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/><text x="56" y="25" fill="${color}" font-family="Arial,sans-serif" font-size="13" font-weight="700">${label}</text><text x="56" y="40" fill="${color}" font-family="Arial,sans-serif" font-size="10">TEM LOGO ALI</text></svg>`}
export function commercialDiscount(subtotal,freight,code,config=readMarketplace()){const coupon=code?config.coupons.find(c=>c.code===String(code).toUpperCase()&&c.active):null;if(code&&!coupon)throw Error('Cupom não encontrado ou desativado.');if(coupon&&subtotal<coupon.minimum)throw Error('Valor mínimo do cupom não atingido nesta loja.');const discount=coupon?Math.min(subtotal,Math.round(subtotal*coupon.percent/100)):0;return {discount,freight:config.freeShippingMinimum>0&&subtotal>=config.freeShippingMinimum?0:freight};}

